import React from 'react';

import { IWorkoutPhotoFull } from '@apps/Workouts/@types/workouts.types';
import { showModal } from '@ui-kit/Modal';

interface IWorkoutPhotoItemProps {
  photo: IWorkoutPhotoFull;
  toolbar?: React.ReactNode;
}

const WorkoutPhotoItem: React.FC<IWorkoutPhotoItemProps> = ({ photo, toolbar }) => {
  return (
    <div className="position-relative img-thumbnail p-0 toolbared">
      <img width="100%" src={photo.url_preview} className=" img-thumbnail p-0" />
      <div
        className="position-absolute p-2 d-flex flex-column justify-content-between"
        style={{ inset: 0, cursor: 'pointer' }}
        onClick={(e) => {
          e.ctrlKey ? window.open(photo.url) : showModal({ children: <img src={photo.url} /> });
        }}
      >
        {photo.comment.length > 0 ? (
          <small className="text-light">
            <em>
              <small>{photo.comment}</small>
            </em>
          </small>
        ) : null}
        <aside onClick={(e) => e.stopPropagation()} className="show-on-hover">
          {toolbar}
        </aside>
      </div>
    </div>
  );
};

export default WorkoutPhotoItem;
