import React, { HTMLAttributes } from 'react';

import clsx from 'clsx';

import PohAva from '@ui-kit/Ava';

import { IWorkoutFull } from '../@types/workouts.types';

interface IWorkoutAboutProps extends HTMLAttributes<HTMLDivElement> {
  workout: IWorkoutFull;
}

const WorkoutAbout: React.FC<IWorkoutAboutProps> = ({ workout, ...rest }) => {
  return (
    <small
      {...rest}
      className={clsx('d-flex justify-content-end align-items-center', rest.className)}
    >
      <div className="d-flex justify-content-end align-items-center">
        <small className="text-muted" title={workout.date_upload.toLocaleString()}>
          Загружено: <small>{workout.date_upload.toLocaleDateString()}</small>
        </small>
        &nbsp; &nbsp;
        <small>{workout.user.name}</small>
        &nbsp;
        <PohAva width={16} alt={[workout.user.name].join('')} src={workout.user.photo} />
      </div>

      {(workout.user.id !== workout.trackOwner.id || workout.group) && (
        <div className="text-end text-muted ms-2">
          <small>
            {workout.user.id !== workout.trackOwner.id && (
              <span>
                Трек записан пользователем:{' '}
                {[workout.trackOwner.name, workout.trackOwner.surname].join(' ')}.
              </span>
            )}{' '}
            {workout.group && (
              <div>
                Групповое занятие{' '}
                <a
                  href={`workouts/group/${workout.group.id}`}
                  target="_blank"
                  rel="noreferrer"
                  title={workout.group.name}
                >
                  #{workout.group.id}
                </a>
                .
              </div>
            )}
          </small>
        </div>
      )}
    </small>
  );
};

export default WorkoutAbout;
